import { hookEntries } from "../features/native/adapters.js";
import { hookManifestSchema } from "@barndog-ai/api-contract";
import type { HookHarness } from "../harnesses/types.js";
import type { RuntimeContext } from "../runtime.js";

/** Registered commands with Windows path separators made `/`, so tests match one form. */
export function inspectNative(text: string): string {
  return text.replaceAll("\\\\", "/").replaceAll("\\", "/");
}

/** Inspect the command generated by the public native-entry builder. */
export function registeredHook(
  root: string,
  command: string,
  runtime: RuntimeContext,
  harness: HookHarness = "claude",
) {
  const manifest = hookManifestSchema.parse({
    name: "check",
    description: "Check",
    implementations: {
      [harness]: {
        compatibility: "supported",
        scripts: ["scripts/check.sh"],
        requirements: { commands: [] },
        events: { SessionStart: [{ hooks: [{ type: "command", command }] }] },
      },
    },
  });

  const entry = hookEntries(
    harness,
    { id: "check", root, manifest },
    runtime,
  )[0]!;

  return (entry.value as { hooks: { command: string }[] }).hooks[0]!.command;
}
